COPY app.features (id, project_id, module_id, code, name, current_behavior, tags, status, created_by, row_version, created_at, updated_at, archived_at) FROM stdin;
1	1	2	INPULSE-F-1	用户登录与会话管理	密码使用 Argon2id 校验（M=19MiB、t=2、p=1）；Session Token 仅存 HMAC-SHA-256 哈希；登录消费匿名预认证会话并轮换 CSRF Token，防 Session Fixation；停用与改密在同一事务递增 auth_version 并撤销全部会话；匿名入口直达登录页并按 from 参数回跳。	{认证,Session,CSRF}	ACTIVE	1	1	2026-09-08 03:12:43+00	2026-09-08 03:12:43+00	\N
2	1	2	INPULSE-F-2	系统管理员 MFA 与重认证	管理员强制 TOTP：Secret 以 AEAD 密文存储、恢复码只存 Argon2id 哈希；高风险操作要求管理员密码 + 当前验证码双因子重认证且 5 分钟内有效；验证窗口 ±1 时间步并持久化 last_accepted_step，同一时间步并发仅一个成功。	{MFA,TOTP,高风险操作}	ACTIVE	1	1	2026-09-08 03:31:46+00	2026-09-08 03:31:46+00	\N
3	1	2	INPULSE-F-3	用户管理	仅系统管理员可维护用户：目录只返回 ACTIVE 且未停用用户的 id/name/avatarUrl/isAdmin；新增、编辑、启停与启用全部写审计；停用同事务撤销会话；禁止自停用、自降级，保护最后一名可用 MFA 管理员。	{管理员,账号}	ACTIVE	1	1	2026-09-09 10:40:38+00	2026-09-09 10:40:38+00	\N
4	1	3	INPULSE-F-4	项目创建（含初始成员与未分类模块）	任一启用用户可创建项目；单个事务内完成项目、初始成员、未分类模块、审计、活动、通知与搜索投影七类写入；创建者自动成为成员且不可取消；未分类模块每项目恰好一个。	{项目,事务}	ACTIVE	1	1	2026-09-08 07:41:33+00	2026-09-08 07:41:33+00	\N
5	1	3	INPULSE-F-5	项目成员管理	管理员添加或移除项目成员并保留加入 / 移除历史；被移除成员下一次请求即失去本项目访问权；历史任务保留原负责人，不受成员移除影响。	{成员,权限}	ACTIVE	1	1	2026-09-09 05:01:22+00	2026-09-09 05:01:22+00	\N
6	1	3	INPULSE-F-6	项目编辑、归档与恢复	项目可归档并在归档后恢复；归档方按项目 → 模块 → 功能顺序取锁，避免与子级写入竞态；归档期间子级写入被拒绝。	{归档,恢复}	ACTIVE	1	1	2026-09-10 01:41:26+00	2026-09-10 01:41:26+00	\N
7	1	7	INPULSE-F-8	操作审计与哈希链	仅管理员可读 /audit：支持链选择（SYSTEM 或 PROJECT:<id>）、动作与目标筛选、签名游标分页、原始快照弹窗；读取需 5 分钟内双因子重认证，普通成员返回 403。	{审计,管理员}	ACTIVE	1	1	2026-09-08 11:11:39+00	2026-09-08 11:11:39+00	\N
8	1	4	INPULSE-F-13	功能档案	功能挂在模块下，含当前行为描述与标签，支持归档与恢复；功能档案是任务与迭代记录的归属锚点。	{功能,档案}	ACTIVE	1	1	2026-09-08 09:29:13+00	2026-09-08 09:29:13+00	\N
9	1	4	INPULSE-F-14	功能级任务	任务按功能或模块立项：功能级任务必须绑定 feature_id，模块级任务 feature_id 为空；含负责人、优先级、截止时间与影响功能，负责人必须是项目活跃成员。	{任务,功能}	ACTIVE	1	1	2026-09-09 10:25:59+00	2026-09-09 10:25:59+00	\N
10	1	4	INPULSE-F-16	任务状态流转与历史保留	TODO / DONE / CANCELED 三态与不可跳转的状态机；完成需填写完成说明并写入 task_status_history 快照；历史必须首条起于 NULL、链式连续且时间不倒退，DONE 任务的末条快照与任务完成信息一致。	{任务,状态机}	ACTIVE	1	1	2026-09-10 01:35:10+00	2026-09-10 01:35:10+00	\N
